import {PRIVACY_CONTACT,requestEmail} from './contact.js?v=14';
export function mountPrivacy(){
 const host=document.createElement('dialog');host.className='privacy-surface privacy-dialog';host.id='privacy-settings';host.setAttribute('aria-label','Personal data and privacy requests');
 host.innerHTML=`<div class="privacy-dialog-heading"><h2>Personal data &amp; privacy</h2><button type="button" class="privacy-close" aria-label="Close privacy settings">×</button></div><p>Request information about personal data handled by Orbit Studio, such as details in messages you send us. This version has no user accounts or account database.</p><section class="privacy-section"><h3>Access your personal data</h3><p>Ask what personal information we hold about you, why it is used, and who it has been shared with.</p><a class="privacy-button" href="${requestEmail('access')}">Request access</a></section><section class="privacy-section"><h3>Correct your personal data</h3><p>Ask us to correct, complete, or update personal information we hold about you.</p><a class="privacy-button" href="${requestEmail('correct')}">Request a correction</a></section><section class="privacy-section"><h3>Delete your personal data</h3><p>Ask us to erase personal information where applicable. We will explain any retention required for a lawful purpose.</p><a class="privacy-button" href="${requestEmail('erase')}">Request personal data deletion</a></section><p class="privacy-small">These links open an email draft. Review and send it yourself. Nothing is sent or deleted automatically. Project backups and preset editing remain in the editor.</p><div class="privacy-bottom"><a href="./privacy.html">Privacy notice, consent withdrawal &amp; complaints</a><a href="mailto:${PRIVACY_CONTACT.email}">${PRIVACY_CONTACT.email}</a></div>`;
 document.body.append(host);host.querySelector('.privacy-close').onclick=()=>host.close();
 for(const trigger of document.querySelectorAll('[data-privacy-open]'))trigger.addEventListener('click',event=>{event.preventDefault();host.showModal();});
 return host;
}
